// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MultiplicatorX3 c;

    function setUp() public { c = new MultiplicatorX3(); }

    // The Owner of c is this test contract (msg.sender at deploy time);
    // it must be able to accept the Ether that withdraw() sends back.
    receive() external payable {}

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        // Keep the fuzzed deposit in a wide but realistic Ether range.
        amount = bound(amount, 0, 1e30);

        // Fund the test contract (which is c's Owner) with the fuzzed amount.
        vm.deal(address(this), amount);

        // Owner calls the payable withdraw(), which in C transfers
        // the contract's whole balance (balance + msg.value) back to Owner.
        bool ok = true;
        try c.withdraw{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: after any Owner withdraw() (with any admissible amount),
        // the correct contract holds no Ether. The mutant, having no transfer,
        // retains balance + msg.value > 0 whenever amount > 0.
        assertTrue(ok && address(c).balance == 0);
    }
}
